fixtures.src/compliance/types.ts:
export type ComplianceSeverity = "Low" | "Medium" | "High" | "Critical";

export type ComplianceStandard = "CIS-Azure-Foundations-v2.0" | "NIST-SP-800-53-R5" | "GDPR" | "PCI-DSS-v4.0";

export interface AzureResourceDefinition {
  readonly id: string;
  readonly name: string;
  readonly type: string;
  readonly location: string;
  readonly properties: Readonly<Record<string, unknown>>;
  readonly tags?: Readonly<Record<string, string>>;
  readonly identity?: {
    readonly type?: "None" | "SystemAssigned" | "UserAssigned" | "SystemAssigned, UserAssigned";
  };
}

export interface ComplianceViolation {
  readonly ruleId: string;
  readonly ruleName: string;
  readonly standard: ComplianceStandard;
  readonly severity: ComplianceSeverity;
  readonly resourceId: string;
  readonly resourceType: string;
  readonly message: string;
  readonly remediationGuide: string;
  readonly remediationCliCommand?: string;
}

export interface CompliancePolicyRule {
  readonly id: string;
  readonly name: string;
  readonly standard: ComplianceStandard;
  readonly severity: ComplianceSeverity;
  readonly targetResourceTypes: readonly string[];
  evaluate(resource: AzureResourceDefinition): ComplianceViolation | null;
}

export interface ComplianceAuditReport {
  readonly auditId: string;
  readonly evaluatedAt: string;
  readonly totalResourcesAudited: number;
  readonly compliantResourceCount: number;
  readonly nonCompliantResourceCount: number;
  readonly complianceScorePercentage: number;
  readonly violations: readonly ComplianceViolation[];
  readonly violationsBySeverity: Readonly<Record<ComplianceSeverity, number>>;
}

