import type {
  AzureResourceDefinition,
  CompliancePolicyRule,
  ComplianceAuditReport,
  ComplianceViolation,
} from "./types.js";

export class AzureComplianceEngine {
  private readonly rules: Map<string, CompliancePolicyRule> = new Map();

  public registerRule(rule: CompliancePolicyRule): void {
    this.rules.set(rule.id, rule);
  }

  public registerRules(rules: readonly CompliancePolicyRule[]): void {
    for (const rule of rules) {
      this.registerRule(rule);
    }
  }

  public evaluateResourceGraph(
    resources: readonly AzureResourceDefinition[],
    auditId = `audit-${Date.now()}`
  ): ComplianceAuditReport {
    throw new Error("evaluateResourceGraph not implemented");
  }

  public filterViolationsBySeverity(
    violations: readonly ComplianceViolation[],
    severity: string
  ): readonly ComplianceViolation[] {
    return violations.filter((v) => v.severity === severity);
  }
}
